    Julian_Epoch_to_MJD(jepoch):
       Convert Julian Epoch to Modified Julian Date (MJD)
    """
def Julian_Epoch_to_MJD(jepoch: Any) -> object {
    return (51544.5 + ((jepoch - 2000.0) * 365.25));
}

