"""
    Multiplies a matrix with a vector and returns the result as a new vector.
    :param matrix: Matrix
    :param vector: vector
    :return: vector
    """
def matrixMultVec(matrix: Any, vector: Any) -> object {
    new_vector = [];
    x = 0;
    for row in matrix {
        for (index, number) in enumerate(row) {
            x += number * vector[index];
        }
        new_vector.append(x);
        x = 0;
    }
    return new_vector;
}

